documents.implicit:
yamaa: "1.0"
type: spec
domain: ADVS
keys: [STUDYID, USUBJID, VSDY]
input:
  VS: {path: vs.csv, types: {VSDTC: date, VSDY: int, SYSBP: float}}
  HOME: {path: home.csv, types: {VSDTC: date, VSDY: int, SYSBP: float}}
  PLAN: {path: plan.csv, key: [USUBJID], types: {DOSENUM: int, PLANDOSE: float}}
  DM: {path: dm.csv, key: [USUBJID], types: {RFSTDTC: date, AGE: int}}
intermediates:
  - {id: PL, dataset: PLAN, key: {DOSENUM: VS.USUBJID}}
  - {id: PB, dataset: PLAN, key: [USUBJID], filter: "PLAN.DOSENUM > 0"}
base: VS
output: {path: out.csv, columns: [STUDYID, USUBJID, VSDY, X, C]}
columns:
  - {name: STUDYID, type: str, derivation: VS.STUDYID}
  - {name: USUBJID, type: str, derivation: VS.USUBJID}
  - {name: VSDY, type: int, derivation: VS.VSDY}
  - {name: X, type: float, derivation: 0.0}
  - {name: C, type: str, derivation: "'A'"}

documents.record:
yamaa: "1.0"
type: spec
domain: ADVS
keys: [STUDYID, USUBJID, VSDY]
input:
  VS: {path: vs.csv, types: {VSDTC: date, VSDY: int, SYSBP: float}}
  HOME: {path: home.csv, types: {VSDTC: date, VSDY: int, SYSBP: float}}
  PLAN: {path: plan.csv, key: [USUBJID], types: {DOSENUM: int, PLANDOSE: float}}
