documents.grouped:
yamaa: "1.0"
type: spec
domain: ADVS
keys: [STUDYID, USUBJID]
input:
  VS: {path: vs.csv, types: {VSDTC: date, VSDY: int, SYSBP: float}}
  HOME: {path: home.csv, types: {VSDTC: date, VSDY: int, SYSBP: float}}
  PLAN: {path: plan.csv, key: [USUBJID], types: {DOSENUM: int, PLANDOSE: float}}
  DM: {path: dm.csv, key: [USUBJID], types: {RFSTDTC: date, AGE: int}}
intermediates:
  - {id: PL, dataset: PLAN, key: {DOSENUM: VS.USUBJID}}
  - {id: PB, dataset: PLAN, key: [USUBJID], filter: "PLAN.DOSENUM > 0"}
output: {path: out.csv, columns: [STUDYID, USUBJID, X]}
columns:
  - {name: STUDYID, type: str}
  - {name: USUBJID, type: str}
  - {name: X, type: float}
rows:
  - id: subject
    dataset: VS
    group_by: [VS.STUDYID, VS.USUBJID]
    derivations:
      STUDYID: VS.STUDYID
      USUBJID: VS.USUBJID
      X: 0.0

edits.to:
VSDY: VS.VSDY
X: {flag: {condition: "VS.VSTESTCD + 1 > 2", true_value: 1.0, false_value: 0.0, missing: 0.0}}
C: HOME.VSTESTCD

VSDY: VS.VSDY
X: {flag: {condition: "VS.VSTESTCD + 1 > 2", true_value: 1.0, false_value: 0.0, missing: 0.0}}
C: HOME.VSTESTCD

  - {id: Q, dataset: PLAN, key: {USUBJID: HOME.USUBJID}}
  - {id: P, dataset: HOME, key: [USUBJID], derivations: {D: {str_extract: {source: Q.DOSENUM, pattern: "^(?=A)", group: 1}}}}
base: VS

  - {id: P, dataset: PLAN, key: [USUBJID], filter: "XX.Y > 1"}
  - {id: Q, dataset: PLAN, key: [USUBJID], derivations: {E: DM.RFSTDTC}, verifications: [{unique: [USUBJID]}]}
base: VS

  - {id: P, dataset: PLAN, key: [USUBJID], filter: "XX.Y > 1"}
  - {id: Q, dataset: PLAN, key: [USUBJID], derivations: {E: DM.RFSTDTC}, verifications: [{unique: [USUBJID]}]}
base: VS
